#include <future>
#include <vector>

std::vector<int> mapAsync(const std::vector<int>& inputs, int (*work)(int))
{
    std::vector<std::future<int>> pending{};
    pending.reserve(inputs.size());
    for (int input : inputs)
    {
        pending.push_back(std::async(std::launch::async, work, input));
    }
    std::vector<int> results{};
    results.reserve(inputs.size());
    for (std::future<int>& future : pending)
    {
        results.push_back(future.get());
    }
    return results;
}

unitTests:
#include <chrono>
#include <thread>
int slowSquare(int x) { std::this_thread::sleep_for(std::chrono::milliseconds{ 150 }); return x * x; }
int triple(int x) { return x * 3; }
TEST("results come back in input order") { CHECK_EQ(mapAsync({ 1, 2, 3, 4 }, triple), (std::vector<int>{ 3, 6, 9, 12 })); CHECK(mapAsync({}, triple).empty()); }
TEST("the tasks really run at the same time") {
    const auto start{ std::chrono::steady_clock::now() };
    const auto results{ mapAsync({ 1, 2, 3, 4, 5, 6 }, slowSquare) };
    const auto ms{ std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count() };
    CHECK_EQ(results, (std::vector<int>{ 1, 4, 9, 16, 25, 36 }));
    CHECK(ms < 600);   // six tasks of 150 ms each would take 900 ms one after another
}

